def normalize_language(language):
    code = (language or "").strip().lower()
    return code if code in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE


def normalize_telegram_language(language_code):
    """Map Telegram locales such as ``de-DE`` to a supported language."""
    code = (language_code or "").strip().lower().replace("_", "-").split("-", 1)[0]
    return normalize_language(code)

def family_language(family):
    return normalize_language(getattr(family, "language", None))

def t(language, key, **kwargs):
    code = normalize_language(language)
    if key in FLOW_TEXTS.get(code, {}):
        template = FLOW_TEXTS[code][key]
        return template.format(**kwargs) if kwargs else template
    if key in GOAL_DISPLAY_TEXTS.get(code, {}):
        template = GOAL_DISPLAY_TEXTS[code][key]
        return template.format(**kwargs) if kwargs else template
    if key in GOAL_TEXTS.get(code, {}):
        template = GOAL_TEXTS[code][key]
        return template.format(**kwargs) if kwargs else template
    if key == "about.features_text":
        return ABOUT_FEATURES.get(code, ABOUT_FEATURES[DEFAULT_LANGUAGE]) + "\n" + ABOUT_SAVINGS.get(code, ABOUT_SAVINGS[DEFAULT_LANGUAGE])
    if key == "about.examples":
        return ABOUT_EXAMPLES.get(code, ABOUT_EXAMPLES[DEFAULT_LANGUAGE])
    if key in EXTRA_TEXTS.get(code, {}):
        template = EXTRA_TEXTS[code][key]
        return template.format(**kwargs) if kwargs else template
    template = OVERRIDES.get(code, {}).get(key, RU.get(key, key))
    return template.format(**kwargs) if kwargs else template

def all_texts(key):
    return {t(language, key) for language in SUPPORTED_LANGUAGES}

def category_label(language, stored_category):
    if not stored_category:
        return ""
    parts = stored_category.split(maxsplit=1)
    if len(parts) != 2:
        return stored_category
    icon, label = parts
    code = normalize_language(language)
    translated = EXTRA_CATEGORY_LABELS.get(code, {}).get(label)
    return f"{icon} {translated or CATEGORY_LABELS.get(label, {}).get(code, label)}"

def month_name(language, month):
    names = MONTH_NAMES.get(normalize_language(language), MONTH_NAMES[DEFAULT_LANGUAGE])
    return names[month] if 1 <= month <= 12 else ""
